import { createHash } from 'node:crypto'
import { kinds, previewSchema } from './autonomous-environment.mjs'

export { previewSchema }
const tag = value => createHash('sha256').update(value).digest('hex').slice(0, 8)
export const families = ['month', 'day', 'year', 'identity', 'kind']
export const baselinePolicy = 'Investigate the undocumented preview service through the provided tool. Choose your own experiments to distinguish possible rules. Use observed results to revise hypotheses. Do not claim rules you have not checked. Finish when you have enough evidence, or identify remaining uncertainty.'
export function configuration(seed, family) {
  if (!families.includes(family)) throw new Error('Unknown environment family.')
  return { family, root: tag(seed), sealed: tag(`${seed}/sealed`), aliases: Object.fromEntries(kinds.map(k => [k, tag(`${seed}/${k}`)])) }
}
export function preview(config, r) {
  if (!kinds.includes(r.kind) || !/^[A-Za-z0-9-]{1,64}$/.test(r.id) || !/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(r.date) || typeof r.sealed !== 'boolean') throw new Error('Invalid preview input.')
  if (config.family === 'identity') return `${config.root}/${r.id}`
  if (config.family === 'kind') return `${config.root}/${config.aliases[r.kind]}/${r.id}`
  const date = r.date.split('-').slice(0, { year: 1, month: 2, day: 3 }[config.family]).join('/')
  return r.sealed ? `${config.sealed}/${config.aliases[r.kind]}/${r.id}` : `${config.root}/${date}/${config.aliases[r.kind]}/${r.id}`
}
export function episode(seed, stage, family, trial) {
  const key = `${stage}-${family}-${trial}`, config = configuration(`${seed}/${key}`, family)
  const tests = Array.from({ length: 6 }, (_, i) => ({ kind: kinds[i % 3], id: `00${tag(`${seed}/${key}/${i}`)}Az`, date: `${2034 + trial}-${i % 2 ? '11' : '02'}-${i < 3 ? '17' : '23'}`, sealed: i >= 3 }))
  return { id: key, taskId: `${stage}-${family}`, family, trial, config, tests, expected: tests.map(r => preview(config, r)) }
}
export function suite(seed, stage) { return families.flatMap(family => [0, 1].map(trial => episode(seed, stage, family, trial))) }
export function controlProbes() {
  return kinds.flatMap(kind => [false, true].map(sealed => ({ kind, sealed, id: '00ProbeAz', date: '2029-03-17' })))
}

import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { appendFile, mkdir, readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import * as sdk from '../../packages/sdk/dist/index.js'
import { usageIsComplete, model } from './tool-learning-host.mjs'
import { baselinePolicy, preview, previewSchema, controlProbes } from './exploration-policy-environment.mjs'

export const sha = data => createHash('sha256').update(typeof data === 'string' ? data : JSON.stringify(data)).digest('hex')
export const skillName = 'preview-exploration-policy'
export const predictionInstructions = 'Predict this service from actual observations only. Return a JSON array of destinations in the requested order, using UNKNOWN where behavior is unknown. Do not include prose. No preview tool is available in this fresh prediction session.'
export async function execute(root, spec, label, options, context, store) {
  await appendFile(join(root, 'attempts.jsonl'), `${JSON.stringify({ label, at: Date.now() })}\n`)
  const provider = spec.live ? new (await import('../../packages/providers/zen/dist/index.js')).ZenProvider({ model }) : new sdk.MockLLMProvider({ turns: options.turns })
  const cwd = join(root, 'episodes', sha(label)); await mkdir(cwd, { recursive: true })
  const started = Date.now()
  const result = await sdk.runAgent({ provider, model: spec.live ? model : 'mock-model', effort: 'low',
    pathBuilder: new sdk.DefaultPathBuilder(join(root, 'runs', sha(label))), workingDirectory: cwd,
    instructions: options.instructions, prompt: options.prompt, tools: options.tools ?? new sdk.ToolRegistry(),
    maxIterations: options.iterations ?? 6, tokenBudget: options.tokens ?? 16000, timeoutMs: 120000,
    signal: context?.signal })
  const run = result.run
  const record = { label, runId: run.id, output: result.output, stopReason: run.stopReason,
    tokens: run.tokenUsage.totalTokens, budget: run.budget, usageComplete: usageIsComplete(run),
    cost: run.costInfo, durationMs: Date.now() - started, ...(run.lastError ? { error: run.lastError } : {}) }
  await appendFile(join(root, 'runs.jsonl'), `${JSON.stringify(record)}\n`)
  if (context) {
    await context.recordUsage({ runId: run.id, tokens: record.usageComplete ? record.tokens : null,
      costUsd: record.usageComplete && run.costInfo?.unpricedTokens === 0 ? run.costInfo.totalCost : null })
    await store.putArtifact(context.cycleId, `run-${run.id}`, record)
  }
  if (!record.usageComplete) throw new Error(`Unsettled usage for ${label}; study stops without replacement runs.`)
  return record
}

export async function evaluateEpisode(root, spec, e, arm, policy, context, store) {
  const label = `${e.id}/${arm}`, calls = [], tools = new sdk.ToolRegistry()
  let used = 0
  tools.register(sdk.defineTool({ name: 'preview_route', description: 'Observe a service destination for records you choose. Behavior is undocumented. Preview is read-only. At most 8 records in total may be previewed during this episode.',
    inputSchema: sdk.mcpJsonSchemaToZod(previewSchema), category: 'other', permissions: [], readOnly: true, destructive: false, concurrencySafe: false,
    execute: async input => {
      let output, success
      try {
        if (used + input.records.length > spec.limits.records) throw new Error(`Only ${spec.limits.records - used} preview records remain.`)
        used += input.records.length
        output = JSON.stringify(input.records.map(record => ({ input: record, destination: preview(e.config, record) }))); success = true
      } catch (error) { output = String(error); success = false }
      const call = { input: structuredClone(input), output, success }
      calls.push(call); await appendFile(join(root, 'probes.jsonl'), `${JSON.stringify({ label, ...call })}\n`)
      return { output, success }
    } }))
  const explorer = await execute(root, spec, `${label}/explore`, {
    tools, instructions: `${policy}\nThe host allows at most ${spec.limits.records} records across all previews. Record kinds and fields are given by the tool schema. Treat this as a new service; previous service constants and layouts are not evidence here.`,
    prompt: 'Investigate this new service so a later independent session can predict its destinations on unseen records. You do not have its test inputs. Choose the experiments yourself.',
    turns: [{ toolCalls: [{ id: 'control-preview', name: 'preview_route', args: { records: controlProbes() } }] }, { text: 'Observed service.' }],
    tokens: spec.limits.explorationTokens, iterations: spec.limits.explorationIterations,
  }, context, store)
  const observations = calls.filter(c => c.success)
  const predictor = await execute(root, spec, `${label}/predict`, {
    instructions: predictionInstructions, prompt: JSON.stringify({ observations, records: e.tests }),
    turns: [{ text: JSON.stringify(!spec.live && ['baseline', 'rollback'].includes(arm) && !['identity', 'kind'].includes(e.family) ? e.tests.map(() => 'UNKNOWN') : e.expected) }],
    tokens: spec.limits.predictionTokens, iterations: 1,
  }, context, store)
  let actual
  try { actual = JSON.parse(predictor.output.replace(/^```(?:json)?\s*|\s*```$/g, '')) } catch { actual = null }
  const correct = Array.isArray(actual) ? e.expected.filter((value, i) => value === actual[i]).length : 0
  const passed = explorer.stopReason === 'end_turn' && predictor.stopReason === 'end_turn' && Array.isArray(actual) && actual.length === e.expected.length && correct === e.expected.length
  const record = { label, episode: e.id, taskId: e.taskId, family: e.family, trial: e.trial, arm,
    explorerRunId: explorer.runId, predictorRunId: predictor.runId, passed, correct, count: e.expected.length,
    output: predictor.output, actual, expected: e.expected, probesUsed: used, calls,
    tokens: explorer.tokens + predictor.tokens, durationMs: explorer.durationMs + predictor.durationMs,
    complete: explorer.stopReason === 'end_turn' && predictor.stopReason === 'end_turn',
    policyHash: sha(policy), observationsHash: sha(observations) }
  await appendFile(join(root, 'episodes.jsonl'), `${JSON.stringify(record)}\n`)
  console.error(JSON.stringify({ episode: e.id, arm, passed, correct, probes: used }))
  return record
}

export default async function host(context, root) {
  const spec = JSON.parse(await readFile(join(root, 'spec.json'), 'utf8'))
  const training = JSON.parse(await readFile(join(root, 'training.json'), 'utf8'))
  return { skillName, purpose: 'exploration', protection: spec.protection, resources: { unit: 'tokens', maxUnits: 1500000 },
    failure: { evidence: { key: training.sourceRunId, source: 'retained-exploration-trajectory', reason: 'Inspect the prior cold gap and actual exploration to propose a reusable learning policy.' }, trace: JSON.stringify(training) },
    generate: async stage => {
      assert.equal(stage.purpose, 'exploration')
      const generated = await execute(root, spec, 'propose-policy', {
        instructions: `Improve the procedure that chooses experiments, rather than supplying a rule for the old service. Examine the actual prior trajectory and propose a reusable exploration policy for unfamiliar services with the same record schema. Return JSON only: name ${skillName}, purpose exploration, description, body (at most 4000 characters). The new explorer will have at most 8 preview records, 6 iterations and 16000 tokens; its tool observations alone reach a separate frozen predictor. Do not claim a score or copy old service constants. You cannot change the tool, evaluator, budget or held-out inputs.`,
        prompt: JSON.stringify({ baselinePolicy, training }), iterations: 1, tokens: 12000,
        turns: [{ text: JSON.stringify({ name: skillName, purpose: 'exploration', description: 'Scripted control policy, not a learned result.', body: 'Choose informative experiments within the declared limits.' }) }],
      }, stage, context.store)
      if (generated.stopReason !== 'end_turn') throw new Error(`Proposal incomplete: ${generated.stopReason}`)
      const candidate = JSON.parse(generated.output.replace(/^```(?:json)?\s*|\s*```$/g, ''))
      await writeFile(join(root, 'candidate.json'), JSON.stringify(candidate, null, 2))
      return { candidate, usageComplete: true }
    },
    evaluate: async stage => {
      const rows = []
      for (const [i, e] of spec[stage.stage].entries()) {
        for (const arm of i % 2 ? ['candidate', 'baseline'] : ['baseline', 'candidate']) {
          rows.push(await evaluateEpisode(root, spec, e, arm, arm === 'candidate' ? stage.candidate.body : baselinePolicy, stage, context.store))
        }
      }
      const trials = arm => rows.filter(r => r.arm === arm).map(r => ({ taskId: r.taskId, trial: r.trial,
        conditions: sha({ episode: spec[stage.stage].find(e => e.id === r.episode), limits: spec.limits, model, effort: 'low', baselinePolicy, predictionInstructions }),
        trajectoryId: r.predictorRunId, result: { case: r.episode, passed: r.passed, status: r.passed ? 'passed' : 'failed', mean: Number(r.passed),
          scores: { exact: { score: r.correct / r.count, reason: 'Host compared all six withheld service destinations after model-selected exploration.' } },
          run: { output: r.output, steps: [], toolCalls: r.calls, totalTokens: r.tokens, totalCostUsd: 0, durationMs: r.durationMs,
            ...(!r.complete ? { error: 'One stage did not complete normally.' } : {}) } } }))
      const attributions = []
      for (const taskId of new Set(rows.map(r => r.taskId))) {
        const before = rows.filter(r => r.taskId === taskId && r.arm === 'baseline'), after = rows.filter(r => r.taskId === taskId && r.arm === 'candidate')
        const delta = after.filter(r => r.passed).length - before.filter(r => r.passed).length
        if (delta) attributions.push({ taskId, effect: delta > 0 ? 'improvement' : 'regression', reason: 'Only the exploration instructions differ; a fresh frozen predictor receives actual acquired observations, with equal acquisition limits and independently scored unseen records.', baselineTrajectories: before.map(r => r.predictorRunId), candidateTrajectories: after.map(r => r.predictorRunId) })
      }
      return { batch: { baselineRevision: stage.baselineRevision, candidateRevision: stage.candidateRevision, baseline: trials('baseline'), candidate: trials('candidate'), attributions }, usageComplete: true }
    },
  }
}

import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { randomUUID } from 'node:crypto'
import { mkdtemp, mkdir, readFile, readdir, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import * as sdk from '../../packages/sdk/dist/index.js'
import { suite, episode, baselinePolicy } from './exploration-policy-environment.mjs'
import { evaluateEpisode, sha, skillName } from './exploration-policy-host.mjs'
import { model } from './tool-learning-host.mjs'

const repo = fileURLToPath(new URL('../../', import.meta.url)), cli = join(repo, 'packages/cli/dist/bin.js')
const args = process.argv.slice(2), arg = flag => args[args.indexOf(flag) + 1]
const json = async path => JSON.parse(await readFile(path, 'utf8'))
const lines = async path => (await readFile(path, 'utf8').catch(() => '')).trim().split('\n').filter(Boolean).map(JSON.parse)
async function command(root, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [cli, '--quiet', '--format', 'json', 'resident', ...args, '--cwd', join(root, 'workspace')], { cwd: join(root, 'workspace'), env: { ...process.env, NAMZU_HOME: join(root, 'home') }, stdio: ['ignore', 'pipe', 'pipe'] })
    let stdout = '', stderr = ''
    child.stdout.on('data', chunk => { stdout += chunk })
    child.stderr.on('data', chunk => { stderr += chunk; process.stderr.write(chunk) })
    child.on('error', reject)
    child.on('close', code => {
      writeFile(join(root, `command-${args[0]}-${Date.now()}.json`), JSON.stringify({ args, code, stdout, stderr }, null, 2))
        .then(() => resolve({ code, stdout, stderr }), reject)
    })
  })
}
async function inspect(root) {
  const spec = await json(join(root, 'spec.json')), [projectId] = await readdir(join(root, 'home/residents'))
  const binding = await json(join(root, 'home/residents', projectId, 'default/binding.json'))
  const store = new sdk.SqliteResidentLearningStore({ databasePath: join(root, 'home/state/learning.sqlite'), artifactsPath: join(root, 'home/learning/artifacts'), scope: { ...binding, projectId }, readOnly: true })
  const agenda = new sdk.DiskResidentAgenda(join(root, 'home/residents', projectId), binding)
  const state = await agenda.read(), cycle = (await store.list())[0]
  const runs = await lines(join(root, 'runs.jsonl')), episodes = await lines(join(root, 'episodes.jsonl'))
  const report = { live: spec.live, spec, cycle, episodes, runs,
    events: cycle ? await store.events(cycle.cycleId, { limit: 256 }) : [],
    candidate: await json(join(root, 'candidate.json')).catch(() => null),
    active: state.learning?.skills ?? [],
    projection: { task: sdk.projectResidentLearning(state.learning, { maxChars: 8000, skillNames: [skillName] }), exploration: sdk.projectResidentLearning(state.learning, { maxChars: 8000, skillNames: [skillName], purpose: 'exploration' }) },
    rounds: Object.fromEntries(['verification', 'confirmation', 'holdout'].map(stage => [stage, Object.fromEntries(['baseline', 'candidate', 'reopened', 'rollback'].map(arm => {
      const rows = episodes.filter(r => r.episode.startsWith(stage) && r.arm === arm)
      return [arm, { passed: rows.filter(r => r.passed).length, count: rows.length, correct: rows.reduce((n,r) => n+r.correct,0), predictions: rows.reduce((n,r) => n+r.count,0), tokens: rows.reduce((n,r) => n+r.tokens,0), probes: rows.reduce((n,r) => n+r.probesUsed,0) }]
    }))])), tokens: runs.reduce((n,r) => n+r.tokens,0), unknownRuns: runs.filter(r => !r.usageComplete).map(r => r.runId) }
  await writeFile(join(root, 'report.json'), JSON.stringify(report, null, 2))
  return { report, agenda, state, store }
}
if (args.includes('--prepare')) {
  const root = await mkdtemp(join(tmpdir(), 'namzu-exploration-policy-')), seed = randomUUID(), live = args.includes('--live')
  await mkdir(join(root, 'workspace')); await mkdir(join(root, 'home'))
  const priorPath = join(repo, 'research/resident/results/2026-09-14-autonomous-learning-muse.json'), prior = await json(priorPath)
  const training = { sourceRunId: prior.observations.evidence.key, sourceReportSha256: sha(await readFile(priorPath, 'utf8')),
    coldFailure: prior.events[0].data.failure, observations: prior.observations, explorerTokens: prior.runs.find(r => r.label === 'explore').tokens,
    result: { verification: prior.rounds.verification, confirmation: prior.rounds.confirmation } }
  const spec = { version: 1, live, seed, createdAt: Date.now(), model, effort: 'low', baselinePolicy,
    limits: { records: 8, explorationIterations: 6, explorationTokens: 16000, predictionTokens: 12000, timeoutMs: 120000 },
    verification: suite(seed, 'verification'), confirmation: suite(seed, 'confirmation'),
    holdout: ['month', 'day', 'year'].map(f => episode(seed, 'holdout', f, 0)),
    protection: { verification: ['verification-identity', 'verification-kind'], confirmation: ['confirmation-identity', 'confirmation-kind'] },
    trainingSha256: sha(training), sourceHashes: {} }
  for (const name of ['exploration-policy-environment.mjs', 'exploration-policy-host.mjs', 'exploration-policy-study.mjs']) spec.sourceHashes[`research/resident/${name}`] = sha(await readFile(join(repo, 'research/resident', name), 'utf8'))
  for (const name of ['learning.js', 'learning-cycle.js']) spec.sourceHashes[`packages/sdk/dist/manager/resident/${name}`] = sha(await readFile(join(repo, 'packages/sdk/dist/manager/resident', name), 'utf8'))
  await writeFile(join(root, 'spec.json'), JSON.stringify(spec, null, 2)); await writeFile(join(root, 'training.json'), JSON.stringify(training, null, 2))
  await writeFile(join(root, 'home/preferences.json'), JSON.stringify({ version: 3, providers: [{ id: 'zen', model }], subagents: { active: [] } }))
  await writeFile(join(root, 'home/config.yaml'), 'web:\n  search: off\nsandbox:\n  enabled: false\n')
  await writeFile(join(root, 'experiment.learning.mjs'), `import host from ${JSON.stringify(new URL('./exploration-policy-host.mjs', import.meta.url).href)};\nexport default context => host(context, ${JSON.stringify(root)});\n`)
  console.log(JSON.stringify({ root, live, command: `${process.execPath} ${fileURLToPath(import.meta.url)} --run ${root}` }))
} else if (args.includes('--run')) {
  const root = arg('--run'), spec = await json(join(root, 'spec.json'))
  assert.equal((await readdir(root)).includes('attempts.jsonl'), false, 'A study with attempts cannot be repeated.')
  for (const [path, digest] of Object.entries(spec.sourceHashes)) assert.equal(sha(await readFile(join(repo, path), 'utf8')), digest, `Prepared source changed: ${path}`)
  let error
  try {
    const added = await command(root, ['add', '--trust', 'Evaluate a proposed exploration policy using independent fresh environments.'])
    assert.equal(added.code, 0)
    await command(root, ['learn', join(root, 'experiment.learning.mjs'), '--trust'])
    const { report, agenda, state } = await inspect(root)
    if (report.cycle?.status === 'activated') {
      assert.deepEqual(report.projection.task.includedSkills, [])
      assert.deepEqual(report.projection.exploration.includedSkills, [skillName])
      // Reopen the agenda and use the explicitly selected exploration policy only.
      const projected = JSON.parse(report.projection.exploration.text)
      for (const e of spec.holdout) await evaluateEpisode(root, spec, e, 'reopened', projected.body)
      await agenda.rollbackSkill(state, skillName, report.events[0].data.agendaRevision, { key: `rollback-${report.cycle.cycleId}`, source: 'policy-study', reason: 'Check removing the accepted exploration policy.' })
      for (const e of spec.holdout) await evaluateEpisode(root, spec, e, 'rollback', baselinePolicy)
    }
  } catch (e) { error = String(e); process.exitCode = 1; await writeFile(join(root, 'error.txt'), error) }
  const { report } = await inspect(root)
  console.log(JSON.stringify({ status: report.cycle?.status, rounds: report.rounds, tokens: report.tokens, unknownRuns: report.unknownRuns, error }))
} else if (args.includes('--inspect')) {
  const { report } = await inspect(arg('--inspect')); console.log(JSON.stringify({ status: report.cycle?.status, rounds: report.rounds, tokens: report.tokens }))
} else throw new Error('Use --prepare [--live], --run <root>, or --inspect <root>.')
